# ── Degenerate repetition detection ────────────────────────────────────────

# Minimum n-gram length for sliding-window duplicate detection.
# Shorter values catch more repetitions but increase false positives.
_REPEAT_NGRAM_MIN = 40
# Minimum number of non-overlapping occurrences to trigger.
_REPEAT_NGRAM_COUNT = 3
# Maximum text length to run n-gram analysis on (skip very long outputs).
_REPEAT_NGRAM_MAX_LEN = 8000


def _has_contiguous_repeat(text: str, min_repeat: int = 3) -> bool:
    """Detect if the same sentence/segment appears consecutively ≥ *min_repeat* times.

    Splits on sentence-ending punctuation or newlines, then checks for runs
    of identical (whitespace-normalised) segments.  O(n) — suitable for
    calling on every iteration without measurable overhead.
    """
    if not text:
        return False
    segments = re.split(r'[\n。！？.!?\u3002]', text)
    # Normalise and filter empty
    segs = [s.strip() for s in segments if s.strip()]
    if len(segs) < min_repeat:
        return False
    count = 1
    for i in range(1, len(segs)):
        if segs[i] == segs[i - 1]:
            count += 1
            if count >= min_repeat:
                return True
        else:
            count = 1
    return False


def _has_ngram_repeat(text: str) -> bool:
    """Detect repetition via sliding-window character n-grams.

    Catches repeated blocks that span across punctuation boundaries (which
    the segment-based check misses).  Normalises whitespace before hashing
    so minor spacing differences don't evade detection.

    Strategy: for each window length from _REPEAT_NGRAM_MIN down to 20,
    build a dict of normalised n-gram → list of start positions.  If any
    n-gram appears in ≥ _REPEAT_NGRAM_COUNT non-overlapping positions,
    return True.  Shorter windows are only checked if longer ones found
    nothing, keeping the common-case fast.
    """
    if not text or len(text) < _REPEAT_NGRAM_MIN * _REPEAT_NGRAM_COUNT:
        return False
    if len(text) > _REPEAT_NGRAM_MAX_LEN:
        return False

    # Normalise: collapse whitespace, strip leading/trailing
    norm = re.sub(r'\s+', ' ', text).strip()

    for win in range(_REPEAT_NGRAM_MIN, 19, -5):
        if len(norm) < win * _REPEAT_NGRAM_COUNT:
            continue
        seen: dict[str, list[int]] = {}
        for i in range(len(norm) - win + 1):
            gram = norm[i:i + win]
            if gram not in seen:
                seen[gram] = [i]
            else:
                seen[gram].append(i)

        for positions in seen.values():
            if len(positions) < _REPEAT_NGRAM_COUNT:
                continue
            # Check for non-overlapping occurrences
            non_overlap = 1
            last_end = positions[0] + win
            for p in positions[1:]:
                if p >= last_end:
                    non_overlap += 1
                    last_end = p + win
                    if non_overlap >= _REPEAT_NGRAM_COUNT:
                        return True
    return False


def _has_degenerate_repeat(text: str) -> bool:
    """Combined repetition detector: segment-based OR n-gram-based."""
    return _has_contiguous_repeat(text) or _has_ngram_repeat(text)


def _truncate_repeated_tail(text: str, min_repeat: int = 3) -> str:
    """Remove trailing contiguous repetitions from *text*.

    Keeps the first occurrence of each repeated segment and discards the
    duplicates that follow.  Returns the cleaned text.
    """
    if not text:
        return text
    segments = re.split(r'([\n。！？.!?\u3002])', text)
    # segments alternates: [content, delimiter, content, delimiter, ...]
    # Rebuild into (content, delimiter) pairs
    pairs: list[tuple[str, str]] = []
    i = 0
    while i < len(segments):
        content = segments[i]
        delim = segments[i + 1] if i + 1 < len(segments) else ""
        # Skip trailing empty pairs (produced by re.split when text ends with delimiter)
        if content or delim:
            pairs.append((content, delim))
        i += 2

    if len(pairs) < min_repeat:
        return text

    # Find the longest trailing run of identical (content, delim) pairs
    last_unique_idx = len(pairs) - 1
    for i in range(len(pairs) - 2, -1, -1):
        if pairs[i] == pairs[i + 1]:
            last_unique_idx = i
        else:
            break

    # Check if the run is long enough
    run_len = len(pairs) - last_unique_idx
    if run_len >= min_repeat:
        # Keep up to and including the first occurrence of the repeated segment
        keep_until = last_unique_idx + 1
        return "".join(c + d for c, d in pairs[:keep_until])

    return text
